CREATE FUNCTION pg_temp.check_w(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',message; END IF; END $$;
CREATE FUNCTION pg_temp.reject_w(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 EXECUTE statement;RAISE EXCEPTION 'Unexpected success: %',statement;
 EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>expected THEN RAISE; END IF;END $$;
GRANT EXECUTE ON FUNCTION pg_temp.check_w(boolean,text),pg_temp.reject_w(text,text) TO anon,authenticated,service_role;
CREATE TEMP TABLE wd_tokens AS SELECT c.id,c.professional_id,c.verification_version cv,i.verification_version iv,i.id iid
 FROM public.professional_credentials c JOIN public.professional_external_identities i ON i.professional_id=c.professional_id
 WHERE c.id='e8310000-0000-0000-0003-000000000001';
GRANT SELECT,UPDATE ON wd_tokens TO authenticated,service_role;
SELECT pg_temp.check_w((SELECT verification_status='pending' AND provider_user_id='34' FROM public.professional_external_identities WHERE id=(SELECT iid FROM wd_tokens)),'Legacy name-only identity downgraded');
SELECT pg_temp.check_w((SELECT verification_status='pending' FROM public.professional_credentials WHERE id=(SELECT id FROM wd_tokens)),'Legacy automatic result downgraded');
SELECT pg_temp.check_w((SELECT verification_status='verified' FROM public.professional_credentials WHERE id='e8310000-0000-0000-0003-000000000002'),'Manual credential preserved');
SELECT pg_temp.check_w(EXISTS(SELECT 1 FROM pc_private.external_identity_history WHERE snapshot->>'verification_method'='working_dog_auto'),'Legacy identity evidence preserved');
SET ROLE anon;
SELECT pg_temp.reject_w($q$SELECT public.request_working_dog_identity('https://www.working-dog.com/user/Test-34')$q$,'42501');
SELECT pg_temp.reject_w($q$SELECT * FROM pc_private.external_identity_history$q$,'42501');
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000001',false);
SELECT pg_temp.reject_w($q$UPDATE public.professional_external_identities SET verification_status='verified' WHERE id=(SELECT iid FROM wd_tokens)$q$,'42501');
SELECT pg_temp.reject_w($q$SELECT public.request_working_dog_identity('http://127.0.0.1/user/Test-34')$q$,'22023');
SELECT pg_temp.reject_w($q$SELECT public.request_working_dog_identity('https://www.working-dog.com/results/Test-34')$q$,'22023');
SELECT pg_temp.reject_w($q$SELECT public.review_working_dog_identity((SELECT iid FROM wd_tokens),(SELECT iv FROM wd_tokens),'verified','A made up identity proof')$q$,'42501');
SELECT public.request_working_dog_identity('https://www.working-dog.com/user/Owner-Test-34');
SELECT pg_temp.check_w((SELECT verification_version=(SELECT iv FROM wd_tokens) FROM public.professional_external_identities WHERE id=(SELECT iid FROM wd_tokens)),'Repeated request is idempotent');
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000002',false);
SELECT public.request_working_dog_identity('https://www.working-dog.com/user/Other-Name-34');
SELECT pg_temp.check_w((SELECT count(*)=1 FROM public.professional_external_identities),'RLS only own pending claim');
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000008',false);
SELECT pg_temp.reject_w($q$SELECT public.review_working_dog_identity((SELECT iid FROM wd_tokens),(SELECT iv FROM wd_tokens),'verified','same name')$q$,'22023');
SELECT public.review_working_dog_identity((SELECT iid FROM wd_tokens),(SELECT iv FROM wd_tokens),'verified','Synthetic independent proof of profile control');
SELECT pg_temp.reject_w($q$SELECT public.review_working_dog_identity((SELECT iid FROM wd_tokens),(SELECT iv FROM wd_tokens),'revoked','Stale review must never succeed')$q$,'40001');
UPDATE wd_tokens SET iv=(SELECT verification_version FROM public.professional_external_identities WHERE id=wd_tokens.iid);
SELECT pg_temp.reject_w($q$SELECT public.review_working_dog_identity(id,verification_version,'verified','Duplicate provider account independent proof') FROM public.professional_external_identities WHERE professional_id='e8310000-0000-0000-0000-000000000002'$q$,'23505');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000008',false);
SELECT public.admin_review_credential_version(id,cv,'revoked','Synthetic administrative revocation') FROM wd_tokens;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
UPDATE wd_tokens SET cv=(SELECT verification_version FROM public.professional_credentials WHERE id=wd_tokens.id);
SET ROLE service_role;
SELECT pg_temp.reject_w($q$SELECT public.commit_bound_working_dog_check(id,cv,professional_id,iv,'34','matched',repeat('a',64),'Cannot reverse admin revocation') FROM wd_tokens$q$,'40001');
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000008',false);
SELECT public.admin_review_credential_version(id,cv,'pending','Synthetic new administrative review') FROM wd_tokens;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
UPDATE wd_tokens SET cv=(SELECT verification_version FROM public.professional_credentials WHERE id=wd_tokens.id);
SET ROLE service_role;
SELECT pg_temp.reject_w($q$UPDATE public.professional_external_identities SET verification_status='verified'$q$,'42501');
SELECT pg_temp.reject_w($q$SELECT public.commit_working_dog_check(id,cv,professional_id,'matched',repeat('a',64),'Legacy verifier') FROM wd_tokens$q$,'40001');
SELECT pg_temp.reject_w($q$SELECT pc_private.commit_working_dog_check(id,cv,professional_id,'matched',repeat('a',64),'Private bypass') FROM wd_tokens$q$,'42501');
SELECT pg_temp.reject_w($q$SELECT public.commit_bound_working_dog_check(id,cv,professional_id,iv,'999','matched',repeat('a',64),'Different stable user id') FROM wd_tokens$q$,'22023');
SELECT pg_temp.reject_w($q$SELECT public.commit_bound_working_dog_check(id,cv,'e8310000-0000-0000-0000-000000000002',iv,'34','matched',repeat('a',64),'Wrong actor') FROM wd_tokens$q$,'42501');
SELECT public.commit_bound_working_dog_check(id,cv,professional_id,iv,'34','matched',repeat('b',64),'Bound result',4,'264.38') FROM wd_tokens;
RESET ROLE;
SELECT pg_temp.check_w((SELECT verification_status='verified' FROM public.professional_credentials WHERE id=(SELECT id FROM wd_tokens)),'Valid identity-bound result accepted');
UPDATE wd_tokens SET cv=(SELECT verification_version FROM public.professional_credentials WHERE id=wd_tokens.id);
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000001',false);
SELECT public.request_working_dog_identity('https://www.working-dog.com/user/Changed-Profile-35');
SELECT pg_temp.check_w((SELECT verification_status='pending' FROM public.professional_credentials WHERE id=(SELECT id FROM wd_tokens)),'Owner changing profile invalidates result despite legacy protection trigger');
SELECT pg_temp.check_w((SELECT verification_status='verified' FROM public.professional_credentials WHERE id='e8310000-0000-0000-0003-000000000002'),'Manual qualification unaffected by identity change');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
SET ROLE service_role;
SELECT pg_temp.reject_w($q$SELECT public.commit_bound_working_dog_check(id,cv,professional_id,iv,'34','matched',repeat('b',64),'Stale identity result') FROM wd_tokens$q$,'40001');
RESET ROLE;
SELECT pg_temp.check_w(EXISTS(SELECT 1 FROM pc_private.credential_verification_history WHERE snapshot->>'source_fingerprint'=repeat('b',64) AND snapshot->>'verification_status'='verified'),'Historical verified source kept privately');
SET ROLE anon;
SELECT pg_temp.check_w((SELECT count(*)=0 FROM public.get_public_professional_external_identities('e8310000-0000-0000-0000-000000000001')),'Changed identity no longer public');
SELECT pg_temp.check_w((SELECT count(*)=4 FROM public.search_public_professionals(p_zone_text=>'AreaTest')),'Ordinary trainer search unaffected');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
